import { useState } from 'react';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';

// ─── Vessel Journey waypoints ───────────────────────────────────────
const VESSEL_WAYPOINTS = [
  { key: '>7d',        label: '> 7d',        tip: 'En route — more than 7 days from port' },
  { key: '3d',         label: '3d',          tip: '3-day notice — agent notified, pre-arrival docs filed' },
  { key: '24h',        label: '24h',         tip: '24-hour notice — port authority confirms berth allocation' },
  { key: '12h',        label: '12h',         tip: '12-hour notice — final ETA confirmed, services mobilised' },
  { key: 'pilot',      label: 'Pilot',       tip: 'Pilot boarding — vessel entering port approaches' },
  { key: 'breakwater', label: 'Breakwater',  tip: 'Passing breakwater — vessel inside port limits' },
  { key: 'berth',      label: 'BERTH',       tip: 'All fast — vessel alongside, gangway deployed', interchange: true },
  { key: 'cargo',      label: 'Cargo Ops',   tip: 'Cargo operations in progress' },
  { key: 'unberth',    label: 'Unberth',     tip: 'Vessel singled up, preparing departure' },
  { key: 'pilot-away', label: 'Pilot Away',  tip: 'Pilot disembarked — vessel clear of port limits' },
];

// ─── Service Provider pipeline waypoints ────────────────────────────
const SERVICE_WAYPOINTS = [
  { key: 'identify',    label: 'Identify',    tip: 'Vessel identified in arrival list — potential opportunity' },
  { key: 'prospect',    label: 'Prospect',    tip: 'Initial contact — check vessel history, previous calls' },
  { key: 'quote-sent',  label: 'Quote Sent',  tip: 'Quote sent — confirm within 24h of pilot boarding' },
  { key: 'confirmed',   label: 'Confirmed',   tip: 'Order confirmed — schedule crew and equipment' },
  { key: 'preparation', label: 'Prep',        tip: 'Equipment prepared, team assigned, transport arranged' },
  { key: 'loaded',      label: 'Loaded',      tip: 'Equipment loaded — en route to vessel' },
  { key: 'delivered',   label: 'DELIVERED',   tip: 'Service delivered at berth — job complete', interchange: true },
];

// ─── ETA label for vessel current position ──────────────────────────
const getVesselStageInfo = (eta) => {
  if (!eta) return { key: '>7d', etaLabel: 'ETA unknown' };
  const ms = new Date(eta).getTime() - Date.now();
  const hoursLeft = ms / (1000 * 60 * 60);
  if (hoursLeft < -12)  return { key: 'pilot-away', etaLabel: 'Departed' };
  if (hoursLeft < -4)   return { key: 'unberth',    etaLabel: 'Unberthing' };
  if (hoursLeft < 0)    return { key: 'cargo',       etaLabel: 'At berth' };
  if (hoursLeft < 1)    return { key: 'berth',       etaLabel: 'Berthing' };
  if (hoursLeft < 3)    return { key: 'breakwater',  etaLabel: 'At breakwater' };
  if (hoursLeft < 12)   return { key: 'pilot',       etaLabel: `ETA ~${Math.round(hoursLeft)}h` };
  if (hoursLeft < 24)   return { key: '12h',         etaLabel: `ETA ~${Math.round(hoursLeft)}h` };
  if (hoursLeft < 72)   return { key: '24h',         etaLabel: `ETA ~${Math.round(hoursLeft / 24)}d` };
  if (hoursLeft < 168)  return { key: '3d',          etaLabel: `ETA ~${Math.round(hoursLeft / 24)}d` };
  return { key: '>7d', etaLabel: `ETA ~${Math.round(hoursLeft / 24)}d` };
};

// ─── Determine service stage from vessel relationship / call_status ─
const getServiceStage = (vessel) => {
  if (vessel.call_status === 'called' && vessel.relationship === 'existing') return 'confirmed';
  if (vessel.call_status === 'called') return 'quote-sent';
  if (vessel.relationship === 'new_lead') return 'identify';
  return 'prospect';
};

// ─── Single waypoint node ───────────────────────────────────────────
const Waypoint = ({ wp, isCurrent, isPast, color, isInterchange, onClick, clickable, currentLabel }) => {
  const size = isCurrent ? 'w-3.5 h-3.5' : 'w-2 h-2';
  const fill = isPast || isCurrent
    ? color === 'vessel' ? 'bg-blue-500' : 'bg-[#0B7C6E]'
    : 'bg-transparent';
  const border = isPast || isCurrent
    ? 'border-transparent'
    : color === 'vessel' ? 'border-blue-400/40' : 'border-[#0B7C6E]/40';
  const interchangeRing = isInterchange ? 'ring-2 ring-offset-1 ring-offset-background ring-amber-400/50' : '';
  const pulseClass = (isCurrent || isInterchange) ? 'animate-pulse' : '';

  return (
    <TooltipProvider delayDuration={200}>
      <Tooltip>
        <TooltipTrigger asChild>
          <button
            className={`flex flex-col items-center shrink-0 group ${clickable ? 'cursor-pointer' : 'cursor-default'}`}
            onClick={clickable ? onClick : undefined}
            type="button"
          >
            <div className={`${size} rounded-full border-2 ${fill} ${border} ${interchangeRing} ${pulseClass} transition-all`} />
            <span className={`text-[10px] leading-tight mt-0.5 whitespace-nowrap font-medium transition-colors ${
              isCurrent ? 'font-bold text-foreground' :
              isPast ? 'text-muted-foreground' :
              'text-muted-foreground/40'
            } ${isInterchange ? 'font-bold text-amber-500' : ''}`}>
              {wp.label}
            </span>
            {isCurrent && currentLabel && (
              <span className="text-[8px] text-primary/70 font-medium whitespace-nowrap leading-none">
                {currentLabel}
              </span>
            )}
          </button>
        </TooltipTrigger>
        <TooltipContent side="bottom" className="max-w-[200px] text-xs">
          <p>{wp.tip}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

// ─── Timeline strip ─────────────────────────────────────────────────
const TimelineStrip = ({ waypoints, currentKey, color, onWaypointClick, clickable, currentLabel }) => {
  const currentIdx = waypoints.findIndex(w => w.key === currentKey);
  const lineColor = color === 'vessel' ? 'bg-blue-500' : 'bg-[#0B7C6E]';
  const lineFade = color === 'vessel' ? 'bg-blue-500/15' : 'bg-[#0B7C6E]/15';

  return (
    <div className="flex items-start overflow-x-auto scrollbar-hide">
      {waypoints.map((wp, i) => {
        const isPast = i < currentIdx;
        const isCurrent = i === currentIdx;
        return (
          <div key={wp.key} className="flex items-start shrink-0">
            <Waypoint
              wp={wp}
              isCurrent={isCurrent}
              isPast={isPast}
              color={color}
              isInterchange={wp.interchange}
              onClick={() => onWaypointClick?.(wp.key)}
              clickable={clickable && i > currentIdx}
              currentLabel={isCurrent ? currentLabel : null}
            />
            {i < waypoints.length - 1 && (
              <div className="flex items-center pt-[3px] mx-px">
                <div className={`h-[2px] w-4 sm:w-6 ${i < currentIdx ? lineColor : lineFade}`} />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

// ─── Main component ─────────────────────────────────────────────────
export const DualTimeline = ({ vessel, onServiceStageChange }) => {
  const { key: vesselStage, etaLabel } = getVesselStageInfo(vessel.eta);
  const [serviceStage, setServiceStage] = useState(() => getServiceStage(vessel));

  const handleServiceClick = (key) => {
    setServiceStage(key);
    onServiceStageChange?.(key);
  };

  return (
    <div className="relative mb-3 px-3 py-2.5 rounded-lg border border-border bg-card/50" data-testid="dual-timeline">
      {/* Top strip label */}
      <div className="flex items-center gap-1.5 mb-1">
        <div className="w-1.5 h-1.5 rounded-full bg-blue-500" />
        <span className="text-[9px] font-semibold text-blue-400 uppercase tracking-wider">Vessel Journey</span>
      </div>

      {/* Vessel journey strip */}
      <TimelineStrip
        waypoints={VESSEL_WAYPOINTS}
        currentKey={vesselStage}
        color="vessel"
        clickable={false}
        currentLabel={etaLabel}
      />

      {/* Interchange connector — thin amber line, no label */}
      <div className="flex justify-center my-0.5">
        <div className="w-[1.5px] h-3 bg-amber-400/50 rounded-full" />
      </div>

      {/* Bottom strip label */}
      <div className="flex items-center gap-1.5 mb-1">
        <div className="w-1.5 h-1.5 rounded-full bg-[#0B7C6E]" />
        <span className="text-[9px] font-semibold text-[#0FA390] uppercase tracking-wider">Service Pipeline</span>
        <span className="text-[8px] text-muted-foreground/40 ml-auto italic">(click to advance)</span>
      </div>

      {/* Service provider strip */}
      <TimelineStrip
        waypoints={SERVICE_WAYPOINTS}
        currentKey={serviceStage}
        color="service"
        onWaypointClick={handleServiceClick}
        clickable={true}
        currentLabel="you are here"
      />
    </div>
  );
};
