import { createContext, useContext, useState, useEffect } from 'react';
import '@/App.css';
import { Toaster } from 'sonner';
import { NavigationShell } from '@/components/shared/NavigationShell';
import SalesDashboard from '@/components/sales/SalesDashboard';
import OpsDashboard from '@/components/ops/OpsDashboard';
import ComplianceDashboard from '@/components/compliance/ComplianceDashboard';

const DashboardContext = createContext();
export const useDashboard = () => useContext(DashboardContext);

// Currency conversion rate (approximate)
const USD_TO_INR_RATE = 83.5;

// Currency formatter utility
export const formatCurrency = (amount, currency = 'USD') => {
  if (currency === 'USD') {
    // Convert INR to USD (data is stored in INR)
    const usdAmount = amount / USD_TO_INR_RATE;
    return new Intl.NumberFormat('en-US', {
      style: 'currency',
      currency: 'USD',
      maximumFractionDigits: 0,
    }).format(usdAmount);
  }
  return new Intl.NumberFormat('en-IN', {
    style: 'currency',
    currency: 'INR',
    maximumFractionDigits: 0,
  }).format(amount);
};

// Role tiers: marine (Tier 1), compliance (Tier 2), fleet (Tier 3)
const TIER_RANK = { marine: 1, compliance: 2, fleet: 3 };
export const hasMinTier = (userRole, minTier) => (TIER_RANK[userRole] || 1) >= (TIER_RANK[minTier] || 1);

function App() {
  const [activeView, setActiveView] = useState('sales');
  const [currency, setCurrency] = useState('USD');
  const [userRole, setUserRole] = useState('marine');

  useEffect(() => {
    if (activeView === 'ops' || activeView === 'compliance') {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [activeView]);

  // Auto-redirect from compliance view when switching to Tier 1
  useEffect(() => {
    if (userRole === 'marine' && activeView === 'compliance') {
      setActiveView('sales');
    }
  }, [userRole, activeView]);

  return (
    <DashboardContext.Provider value={{ activeView, setActiveView, currency, setCurrency, userRole, setUserRole }}>
      <div className="min-h-screen bg-background text-foreground">
        <NavigationShell />
        <main>
          {activeView === 'sales' ? <SalesDashboard /> : activeView === 'ops' ? <OpsDashboard /> : <ComplianceDashboard />}
        </main>
        <Toaster
          theme={activeView === 'ops' ? 'dark' : 'light'}
          position="top-right"
          richColors
          closeButton
        />
      </div>
    </DashboardContext.Provider>
  );
}

export default App;
