import axios from 'axios';
import { SEED_VESSELS, SEED_PORT_COUNTS, SEED_FILTERS, SEED_NOTIFICATIONS, SEED_QUOTES, SEED_LEADS, computeStats } from './seedData';

const API_URL = process.env.REACT_APP_BACKEND_URL
  ? `${process.env.REACT_APP_BACKEND_URL}/api`
  : null; // null = no backend, use seed data

const api = API_URL ? axios.create({
  baseURL: API_URL,
  headers: { 'Content-Type': 'application/json' },
}) : null;

// Wrap API calls: try backend first, fall back to seed data
const wrap = (apiFn, fallbackFn) => async (...args) => {
  if (api) {
    try {
      return await apiFn(...args);
    } catch (e) {
      // Backend unavailable, fall through to fallback
    }
  }
  return { data: fallbackFn(...args) };
};

// Filter helpers for seed data
const matchPort = (vessel, portParam) => {
  if (!portParam) return true;
  const ports = portParam.split(',').map(p => p.trim());
  return ports.includes(vessel.port);
};

const matchFilters = (vessel, { port, manager, owner, certStatus, classSociety, shipType } = {}) => {
  if (port && !matchPort(vessel, port)) return false;
  if (manager && !vessel.ship_manager.includes(manager)) return false;
  if (owner && !vessel.ship_owner.includes(owner)) return false;
  if (classSociety && vessel.class_society !== classSociety) return false;
  if (shipType && vessel.vessel_type !== shipType) return false;
  if (certStatus && certStatus !== 'All') {
    if (!vessel.certificates?.some(c => c.status === certStatus)) return false;
  }
  return true;
};

const filterVessels = (port, tab, manager, owner, certStatus, classSociety, shipType, timeWindow) => {
  let vessels = SEED_VESSELS.filter(v => matchFilters(v, { port, manager, owner, certStatus, classSociety, shipType }));
  if (tab === 'overdue') {
    vessels = vessels.filter(v => v.call_status === 'overdue');
  }
  if (tab === 'arriving' && timeWindow) {
    const now = Date.now();
    const daysMs = { '3d': 3, '7d': 7, 'gt7d': 7 };
    const cutoff = now + (daysMs[timeWindow] || 7) * 24 * 60 * 60 * 1000;
    if (timeWindow === 'gt7d') {
      vessels = vessels.filter(v => new Date(v.eta).getTime() > cutoff);
    } else {
      vessels = vessels.filter(v => {
        const eta = new Date(v.eta).getTime();
        return eta >= now && eta <= cutoff;
      });
    }
  }
  return vessels.sort((a, b) => new Date(a.eta) - new Date(b.eta));
};

export const salesAPI = {
  getVessels: wrap(
    (port, tab, manager, owner, certStatus, classSociety, shipType, timeWindow) =>
      api.get('/sales/vessels', { params: { port, tab, manager, owner, cert_status: certStatus, class_society: classSociety, ship_type: shipType, time_window: timeWindow } }),
    (port, tab, manager, owner, certStatus, classSociety, shipType, timeWindow) =>
      filterVessels(port, tab, manager, owner, certStatus, classSociety, shipType, timeWindow)
  ),
  getQuotes: wrap(
    (port, manager, owner, certStatus, classSociety, shipType) =>
      api.get('/sales/quotes', { params: { port, manager, owner, cert_status: certStatus, class_society: classSociety, ship_type: shipType } }),
    () => SEED_QUOTES
  ),
  getLeads: wrap(
    (port, manager, owner, certStatus, classSociety, shipType) =>
      api.get('/sales/leads', { params: { port, manager, owner, cert_status: certStatus, class_society: classSociety, ship_type: shipType } }),
    () => SEED_LEADS
  ),
  getStats: wrap(
    (port, manager, owner, certStatus, classSociety, shipType) =>
      api.get('/sales/stats', { params: { port, manager, owner, cert_status: certStatus, class_society: classSociety, ship_type: shipType } }),
    (port, manager, owner, certStatus, classSociety, shipType) => {
      const filtered = SEED_VESSELS.filter(v => matchFilters(v, { port, manager, owner, certStatus, classSociety, shipType }));
      return computeStats(filtered);
    }
  ),
  getPortCounts: wrap(
    () => api.get('/sales/port-counts'),
    () => SEED_PORT_COUNTS
  ),
  markCalled: wrap(
    (id) => api.post(`/sales/vessels/${id}/call`),
    (id) => {
      const v = SEED_VESSELS.find(v => v.id === id);
      if (v) v.call_status = 'called';
      return { message: 'Call logged' };
    }
  ),
  createQuote: wrap(
    (id) => api.post(`/sales/vessels/${id}/quote`),
    () => ({ message: 'Quote created' })
  ),
  assignEngineer: wrap(
    (id, engineer) => api.post(`/sales/vessels/${id}/assign`, { engineer }),
    () => ({ message: 'Engineer assigned' })
  ),
  addNote: wrap(
    (id, text) => api.post(`/sales/vessels/${id}/note`, { text }),
    () => ({ message: 'Note added' })
  ),
};

export const opsAPI = {
  getJobs: wrap(
    (port, manager, owner, classSociety, shipType) => api.get('/ops/jobs', { params: { port, manager, owner, class_society: classSociety, ship_type: shipType } }),
    () => []
  ),
  updateJobStatus: wrap(
    (id, status) => api.put(`/ops/jobs/${id}/status`, { status }),
    () => ({ message: 'Updated' })
  ),
  getFeed: wrap(
    (port, manager, owner) => api.get('/ops/feed', { params: { port, manager, owner } }),
    (port) => SEED_VESSELS.filter(v => !port || v.port === port)
  ),
  getCertificates: wrap(
    (port, manager, owner) => api.get('/ops/certificates', { params: { port, manager, owner } }),
    () => []
  ),
  getStats: wrap(
    (port, manager, owner) => api.get('/ops/stats', { params: { port, manager, owner } }),
    () => ({ total_jobs: 0, pending: 0, in_progress: 0, completed: 0, flagged: 0, urgent_certificates: 0 })
  ),
};

export const getNotifications = wrap(
  () => api.get('/notifications'),
  () => SEED_NOTIFICATIONS
);
export const markNotificationRead = wrap(
  (id) => api.put(`/notifications/${id}/read`),
  (id) => {
    const n = SEED_NOTIFICATIONS.find(n => n.id === id);
    if (n) n.read = true;
    return { message: 'Marked as read' };
  }
);
export const seedData = wrap(
  () => api.post('/seed'),
  () => ({ message: 'Using static seed data' })
);
export const getFilters = wrap(
  () => api.get('/filters'),
  () => SEED_FILTERS
);

export default api;
