import { useState, useEffect } from 'react';
import { useDashboard, hasMinTier } from '@/App';
import { Bell, RefreshCw, Anchor, X, DollarSign, IndianRupee, AlertTriangle, Info, Users } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Separator } from '@/components/ui/separator';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { getNotifications, markNotificationRead, seedData } from '@/lib/api';
import { toast } from 'sonner';
import { formatDistanceToNow } from 'date-fns';

export const NavigationShell = () => {
  const { activeView, setActiveView, currency, setCurrency, userRole, setUserRole } = useDashboard();
  const showCompliance = hasMinTier(userRole, 'compliance');

  const ROLE_OPTIONS = [
    { value: 'marine', label: 'Ship Chandler / Bunker Supplier' },
    { value: 'compliance', label: 'LSA / FFA Specialist' },
    { value: 'fleet', label: 'Fleet Manager / P&I' },
  ];
  const [notifications, setNotifications] = useState([]);
  const [showNotifs, setShowNotifs] = useState(false);
  const [seeding, setSeeding] = useState(false);
  const unreadCount = notifications.filter(n => !n.read).length;

  const fetchNotifs = async () => {
    try {
      const res = await getNotifications();
      setNotifications(res.data);
    } catch (e) { /* silent */ }
  };

  useEffect(() => {
    fetchNotifs();
    const interval = setInterval(fetchNotifs, 30000);
    return () => clearInterval(interval);
  }, []);

  const handleSeed = async () => {
    setSeeding(true);
    try {
      await seedData();
      toast.success('Data refreshed with new seed');
      window.location.reload();
    } catch (e) {
      toast.error('Failed to refresh data');
    }
    setSeeding(false);
  };

  const markRead = async (id) => {
    await markNotificationRead(id);
    setNotifications(prev => prev.map(n => n.id === id ? { ...n, read: true } : n));
  };

  const getSeverityColor = (severity) => {
    if (severity === 'critical' || severity === 'expired') return 'text-red-500';
    if (severity === 'warning') return 'text-amber-500';
    return 'text-emerald-500';
  };

  const getSeverityBg = (severity) => {
    if (severity === 'critical' || severity === 'expired') return 'bg-red-500/10 border-l-2 border-l-red-500';
    if (severity === 'warning') return 'bg-amber-500/10 border-l-2 border-l-amber-500';
    return 'bg-slate-500/10 border-l-2 border-l-slate-400';
  };

  // Group notifications by severity
  const urgentNotifs = notifications.filter(n => n.severity === 'critical' || n.severity === 'expired');
  const warningNotifs = notifications.filter(n => n.severity === 'warning');
  const infoNotifs = notifications.filter(n => n.severity !== 'critical' && n.severity !== 'expired' && n.severity !== 'warning');

  return (
    <nav
      className="sticky top-0 z-50 border-b border-border bg-background/95 backdrop-blur-md"
      data-testid="navigation-shell"
    >
      <div className="flex items-center justify-between px-4 lg:px-8 h-16">
        {/* Logo */}
        <div className="flex items-center gap-3">
          <div className="w-9 h-9 rounded-lg bg-primary flex items-center justify-center">
            <Anchor className="w-5 h-5 text-primary-foreground" />
          </div>
          <div className="hidden sm:block">
            <h1 className="font-heading text-lg font-bold tracking-tight leading-none">
              Ch16.ai
            </h1>
            <p className="text-[10px] text-muted-foreground tracking-widest uppercase">
              Marine Services Intelligence
            </p>
          </div>
        </div>

        {/* Toggle */}
        <div
          className="flex items-center bg-secondary rounded-full p-1"
          data-testid="dashboard-toggle"
        >
          <button
            data-testid="nav-toggle-sales"
            onClick={() => setActiveView('sales')}
            className={`px-5 py-1.5 rounded-full text-sm font-heading font-semibold tracking-wide transition-all duration-200 ${
              activeView === 'sales'
                ? 'bg-[#0B7C6E] text-white shadow-md'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            SALES
          </button>
          <button
            data-testid="nav-toggle-ops"
            onClick={() => setActiveView('ops')}
            className={`px-5 py-1.5 rounded-full text-sm font-heading font-semibold tracking-wide transition-all duration-200 ${
              activeView === 'ops'
                ? 'bg-[#0FA390] text-black shadow-md'
                : 'text-muted-foreground hover:text-foreground'
            }`}
          >
            OPS
          </button>
          {showCompliance && (
            <button
              data-testid="nav-toggle-compliance"
              onClick={() => setActiveView('compliance')}
              className={`px-5 py-1.5 rounded-full text-sm font-heading font-semibold tracking-wide transition-all duration-200 ${
                activeView === 'compliance'
                  ? 'bg-[#0B7C6E] text-white shadow-md'
                  : 'text-muted-foreground hover:text-foreground'
              }`}
            >
              COMPLIANCE
            </button>
          )}
        </div>

        {/* Actions */}
        <div className="flex items-center gap-2">
          {/* Role Selector */}
          <Select value={userRole} onValueChange={setUserRole}>
            <SelectTrigger
              className="w-52 h-9 text-xs bg-secondary border-border"
              data-testid="role-selector-trigger"
            >
              <SelectValue>
                <span className="flex items-center gap-1.5">
                  <Users className="w-3.5 h-3.5" />
                  {ROLE_OPTIONS.find(r => r.value === userRole)?.label}
                </span>
              </SelectValue>
            </SelectTrigger>
            <SelectContent>
              {ROLE_OPTIONS.map(role => (
                <SelectItem key={role.value} value={role.value} data-testid={`role-option-${role.value}`}>
                  {role.label}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>

          {/* Currency Selector - Only show on Sales screen */}
          {activeView === 'sales' && (
            <Select value={currency} onValueChange={setCurrency}>
              <SelectTrigger 
                className="w-24 h-9 text-xs bg-secondary border-border"
                data-testid="currency-selector-trigger"
              >
                <SelectValue>
                  <span className="flex items-center gap-1.5">
                    {currency === 'USD' ? (
                      <DollarSign className="w-3.5 h-3.5" />
                    ) : (
                      <IndianRupee className="w-3.5 h-3.5" />
                    )}
                    {currency}
                  </span>
                </SelectValue>
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="USD" data-testid="currency-option-usd">
                  <span className="flex items-center gap-2">
                    <DollarSign className="w-3.5 h-3.5" />
                    USD
                  </span>
                </SelectItem>
                <SelectItem value="INR" data-testid="currency-option-inr">
                  <span className="flex items-center gap-2">
                    <IndianRupee className="w-3.5 h-3.5" />
                    INR
                  </span>
                </SelectItem>
              </SelectContent>
            </Select>
          )}

          <Button
            variant="ghost"
            size="icon"
            onClick={handleSeed}
            disabled={seeding}
            data-testid="seed-data-btn"
            title="Refresh seed data"
          >
            <RefreshCw className={`w-4 h-4 ${seeding ? 'animate-spin' : ''}`} />
          </Button>

          <div className="relative">
            <Button
              variant="ghost"
              size="icon"
              onClick={() => setShowNotifs(!showNotifs)}
              data-testid="nav-notifications-btn"
            >
              <Bell className="w-4 h-4" />
              {unreadCount > 0 && (
                <span className="absolute -top-0.5 -right-0.5 w-4 h-4 rounded-full bg-red-500 text-white text-[10px] flex items-center justify-center font-bold">
                  {unreadCount > 9 ? '9+' : unreadCount}
                </span>
              )}
            </Button>

            {showNotifs && (
              <div
                className="absolute right-0 top-12 w-96 bg-card border border-border rounded-lg shadow-xl z-50"
                data-testid="notifications-panel"
              >
                <div className="flex items-center justify-between p-3 border-b border-border">
                  <span className="font-heading font-semibold text-sm">
                    Notifications ({unreadCount} unread)
                  </span>
                  <Button
                    variant="ghost"
                    size="icon"
                    className="h-6 w-6"
                    onClick={() => setShowNotifs(false)}
                  >
                    <X className="w-3 h-3" />
                  </Button>
                </div>
                <ScrollArea className="max-h-96">
                  {notifications.length === 0 ? (
                    <p className="p-4 text-sm text-muted-foreground text-center">
                      No notifications
                    </p>
                  ) : (
                    <div className="p-2 space-y-3">
                      {/* Urgent Notifications */}
                      {urgentNotifs.length > 0 && (
                        <div>
                          <div className="flex items-center gap-1.5 px-2 py-1">
                            <AlertTriangle className="w-3 h-3 text-red-500" />
                            <span className="text-[10px] font-semibold text-red-500 uppercase tracking-wider">
                              Urgent ({urgentNotifs.length})
                            </span>
                          </div>
                          <div className="space-y-1">
                            {urgentNotifs.slice(0, 5).map(n => (
                              <div
                                key={n.id}
                                className={`p-2.5 rounded-md cursor-pointer transition-colors ${getSeverityBg(n.severity)} ${!n.read ? 'opacity-100' : 'opacity-70'}`}
                                onClick={() => markRead(n.id)}
                              >
                                <p className="text-sm font-medium">{n.vessel_name || n.message.split(':')[0]}</p>
                                <p className="text-xs text-muted-foreground mt-0.5">{n.message}</p>
                                <p className="text-[10px] text-muted-foreground mt-1">
                                  {n.port} · {formatDistanceToNow(new Date(n.created_at), { addSuffix: true })}
                                </p>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Warning Notifications */}
                      {warningNotifs.length > 0 && (
                        <div>
                          <div className="flex items-center gap-1.5 px-2 py-1">
                            <AlertTriangle className="w-3 h-3 text-amber-500" />
                            <span className="text-[10px] font-semibold text-amber-500 uppercase tracking-wider">
                              Warning ({warningNotifs.length})
                            </span>
                          </div>
                          <div className="space-y-1">
                            {warningNotifs.slice(0, 5).map(n => (
                              <div
                                key={n.id}
                                className={`p-2.5 rounded-md cursor-pointer transition-colors ${getSeverityBg(n.severity)} ${!n.read ? 'opacity-100' : 'opacity-70'}`}
                                onClick={() => markRead(n.id)}
                              >
                                <p className="text-sm font-medium">{n.vessel_name || n.message.split(':')[0]}</p>
                                <p className="text-xs text-muted-foreground mt-0.5">{n.message}</p>
                                <p className="text-[10px] text-muted-foreground mt-1">
                                  {n.port} · {formatDistanceToNow(new Date(n.created_at), { addSuffix: true })}
                                </p>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}

                      {/* Info Notifications */}
                      {infoNotifs.length > 0 && (
                        <div>
                          <div className="flex items-center gap-1.5 px-2 py-1">
                            <Info className="w-3 h-3 text-slate-400" />
                            <span className="text-[10px] font-semibold text-slate-400 uppercase tracking-wider">
                              Info ({infoNotifs.length})
                            </span>
                          </div>
                          <div className="space-y-1">
                            {infoNotifs.slice(0, 5).map(n => (
                              <div
                                key={n.id}
                                className={`p-2.5 rounded-md cursor-pointer transition-colors ${getSeverityBg(n.severity)} ${!n.read ? 'opacity-100' : 'opacity-70'}`}
                                onClick={() => markRead(n.id)}
                              >
                                <p className="text-sm font-medium">{n.vessel_name || n.message.split(':')[0]}</p>
                                <p className="text-xs text-muted-foreground mt-0.5">{n.message}</p>
                                <p className="text-[10px] text-muted-foreground mt-1">
                                  {n.port} · {formatDistanceToNow(new Date(n.created_at), { addSuffix: true })}
                                </p>
                              </div>
                            ))}
                          </div>
                        </div>
                      )}
                    </div>
                  )}
                </ScrollArea>
              </div>
            )}
          </div>
        </div>
      </div>
    </nav>
  );
};
