const NOW = new Date();
const day = (d) => new Date(NOW.getTime() + d * 24 * 60 * 60 * 1000).toISOString();
const hours = (h) => new Date(NOW.getTime() + h * 60 * 60 * 1000).toISOString();

// Helper: generate cert with status thresholds: expired(<0), critical(<20), warning(<60), safe(>=60)
const cert = (type, daysRemaining) => {
  const status = daysRemaining <= 0 ? 'expired' : daysRemaining < 20 ? 'critical' : daysRemaining < 60 ? 'warning' : 'safe';
  return { type, expiry_date: day(daysRemaining), days_remaining: daysRemaining, status };
};

// Full certificate suite generator for compliance/fleet views
export const generateFullCertificates = (vessel) => {
  const base = vessel.certificates?.[0]?.days_remaining ?? 45;
  const certDefs = [
    { name: 'Safety Equipment Certificate (SEC)', type: 'Statutory', term: 'Full Term' },
    { name: 'Safety Construction Certificate (SCC)', type: 'Statutory', term: 'Full Term' },
    { name: 'Safety Radio Certificate (SRC)', type: 'Statutory', term: 'Short Term' },
    { name: 'Load Line Certificate', type: 'Statutory', term: 'Full Term' },
    { name: 'International Tonnage Certificate (ITC)', type: 'Statutory', term: 'Full Term' },
    { name: 'IOPP Certificate', type: 'Statutory', term: 'Full Term' },
    { name: 'ISPS Certificate', type: 'Statutory', term: 'Full Term' },
    { name: 'Class Certificate', type: 'Class', term: 'Full Term' },
    { name: 'Annual Class Survey', type: 'Class', term: 'Interim' },
    { name: 'SMC (Safety Management Certificate)', type: 'ISM', term: 'Full Term' },
    { name: 'DOC (Document of Compliance)', type: 'ISM', term: 'Full Term' },
    { name: 'CLC Certificate', type: 'Insurance', term: 'Annual' },
    { name: 'Bunker Convention Certificate', type: 'Insurance', term: 'Annual' },
    { name: 'P&I Certificate', type: 'Insurance', term: 'Annual' },
  ];

  return certDefs.map((c, i) => {
    const dr = base + (i * 12) - 25;
    const issueDate = new Date(NOW);
    issueDate.setFullYear(issueDate.getFullYear() - 2);
    issueDate.setMonth(issueDate.getMonth() + i);
    const expiryDate = new Date(NOW.getTime() + dr * 24 * 60 * 60 * 1000);
    const status = dr <= 0 ? 'expired' : dr < 20 ? 'critical' : dr < 60 ? 'warning' : 'safe';
    return {
      name: c.name,
      certNumber: `${vessel.imo_number?.slice(0, 4) || '9999'}-${String(i + 1).padStart(3, '0')}-2025`,
      type: c.type, term: c.term,
      issueDate: issueDate.toISOString(),
      expiryDate: expiryDate.toISOString(),
      extendedUntil: dr <= 0 ? day(30) : null,
      daysRemaining: dr, status,
    };
  });
};

// Full survey suite generator
export const generateFullSurveys = (vessel) => {
  const base = vessel.certificates?.[0]?.days_remaining ?? 45;
  const surveyDefs = [
    { name: 'Annual Survey', category: 'Class' },
    { name: 'Intermediate Survey', category: 'Class' },
    { name: 'Special Survey', category: 'Class' },
    { name: 'Bottom Survey', category: 'Class' },
    { name: 'Tailshaft Survey', category: 'Class' },
    { name: 'Boiler Survey', category: 'Class' },
    { name: 'Safety Equipment Survey', category: 'Statutory' },
    { name: 'IOPP Survey', category: 'Statutory' },
  ];

  return surveyDefs.map((s, i) => {
    const dr = base + (i * 18) - 30;
    const lastDate = new Date(NOW);
    lastDate.setFullYear(lastDate.getFullYear() - 1);
    lastDate.setMonth(lastDate.getMonth() - i);
    const dueFrom = new Date(NOW.getTime() + (dr - 90) * 24 * 60 * 60 * 1000);
    const dueTo = new Date(NOW.getTime() + dr * 24 * 60 * 60 * 1000);
    const assignedDate = new Date(NOW.getTime() + (dr - 30) * 24 * 60 * 60 * 1000);
    const status = dr < 0 ? 'Overdue' : dr < 60 ? 'Due Soon' : 'OK';
    return {
      name: s.name, category: s.category,
      lastSurveyDate: lastDate.toISOString(),
      assignedDate: assignedDate.toISOString(),
      dueFrom: dueFrom.toISOString(),
      dueTo: dueTo.toISOString(),
      status, daysUntilDue: dr,
    };
  });
};

