// Pre-computed stats
export const computeStats = (vessels) => {
  const expiring = vessels.filter(v => v.certificates?.some(c => c.status === 'critical' || c.status === 'expired')).length;
  const overdue = vessels.filter(v => v.call_status === 'overdue').length;
  return {
    arriving_this_week: vessels.length,
    certificates_expiring: expiring,
    overdue_calls: overdue,
    open_quotes: 2,
    new_leads: 1,
    cert_expired: vessels.filter(v => v.certificates?.some(c => c.status === 'expired')).length,
    cert_critical: vessels.filter(v => v.certificates?.some(c => c.status === 'critical')).length,
    cert_warning: vessels.filter(v => v.certificates?.some(c => c.status === 'warning')).length,
  };
};

