// Mock certificate data generator
const generateCertificates = (vessel) => {
  const certTypes = [
    { name: 'Safety Equipment Certificate', type: 'Statutory', term: 'Full Term' },
    { name: 'Safety Construction Certificate', type: 'Statutory', term: 'Full Term' },
    { name: 'Safety Radio Certificate', type: 'Statutory', term: 'Short Term' },
    { name: 'Load Line Certificate', type: 'Statutory', term: 'Full Term' },
    { name: 'International Tonnage Certificate', type: 'Statutory', term: 'Full Term' },
    { name: 'Class Certificate', type: 'Class', term: 'Full Term' },
    { name: 'Annual Class Survey', type: 'Class', term: 'Interim' },
    { name: 'IOPP Certificate', type: 'Statutory', term: 'Full Term' },
  ];

  return certTypes.map((cert, i) => {
    const baseDays = vessel.certificates?.[0]?.days_remaining || 30;
    const daysRemaining = baseDays + (i * 15) - 30;
    const issueDate = new Date();
    issueDate.setFullYear(issueDate.getFullYear() - 2);
    issueDate.setMonth(issueDate.getMonth() + i);
    const expiryDate = new Date();
    expiryDate.setDate(expiryDate.getDate() + daysRemaining);
    const status = daysRemaining < 0 ? 'expired' : daysRemaining < 20 ? 'critical' : daysRemaining < 60 ? 'warning' : 'safe';

    return {
      name: cert.name,
      certNumber: `${vessel.imo_number?.slice(0, 4) || '9999'}-${String(i + 1).padStart(3, '0')}-${new Date().getFullYear()}`,
      type: cert.type,
      term: cert.term,
      issueDate: issueDate.toISOString(),
      expiryDate: expiryDate.toISOString(),
      extendedUntil: daysRemaining < 0 ? new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString() : null,
      daysRemaining,
      status,
    };
  });
};

// Mock survey data generator
const generateSurveys = (vessel) => {
  const surveyTypes = [
    { name: 'Annual Survey', category: 'Class' },
    { name: 'Intermediate Survey', category: 'Class' },
    { name: 'Special Survey', category: 'Class' },
    { name: 'Bottom Survey', category: 'Class' },
    { name: 'Tailshaft Survey', category: 'Class' },
    { name: 'Safety Equipment Survey', category: 'Statutory' },
    { name: 'Safety Construction Survey', category: 'Statutory' },
    { name: 'IOPP Survey', category: 'Statutory' },
  ];

  return surveyTypes.map((survey, i) => {
    const baseDays = vessel.certificates?.[0]?.days_remaining || 30;
    const daysUntilDue = baseDays + (i * 20) - 40;
    const lastSurveyDate = new Date();
    lastSurveyDate.setFullYear(lastSurveyDate.getFullYear() - 1);
    lastSurveyDate.setMonth(lastSurveyDate.getMonth() - i);
    const dueFrom = new Date();
    dueFrom.setDate(dueFrom.getDate() + daysUntilDue - 90);
    const dueTo = new Date();
    dueTo.setDate(dueTo.getDate() + daysUntilDue);
    const status = daysUntilDue < 0 ? 'Overdue' : daysUntilDue < 60 ? 'Due Soon' : 'OK';

    return {
      name: survey.name, category: survey.category,
      lastSurveyDate: lastSurveyDate.toISOString(),
      dueFrom: dueFrom.toISOString(), dueTo: dueTo.toISOString(),
      status, daysUntilDue,
    };
  });
};

