const statusColor = (status) => {
  if (status === 'expired' || status === 'Overdue') return 'bg-red-500';
  if (status === 'critical' || status === 'Due Soon') return 'bg-amber-500';
  if (status === 'warning') return 'bg-amber-400';
  return 'bg-emerald-500';
};

const statusTextColor = (status) => {
  if (status === 'expired' || status === 'Overdue') return 'text-red-500';
  if (status === 'critical' || status === 'Due Soon') return 'text-amber-500';
  if (status === 'warning') return 'text-amber-400';
  return 'text-emerald-500';
};

const formatDate = (dateStr) => {
  if (!dateStr) return '-';
  return new Date(dateStr).toLocaleDateString('en-GB', {
    day: '2-digit', month: 'short', year: 'numeric',
  });
};

