import { useState } from 'react';
import { Checkbox } from '@/components/ui/checkbox';
import { Separator } from '@/components/ui/separator';
import { Switch } from '@/components/ui/switch';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Collapsible,
  CollapsibleContent,
  CollapsibleTrigger,
} from '@/components/ui/collapsible';
import { Ship, PhoneOff, FileText, UserPlus, AlertTriangle, ShieldAlert, ShieldX, ShieldCheck, ChevronDown, ChevronRight } from 'lucide-react';
import { useDashboard, hasMinTier } from '@/App';

const statItems = [
  { key: 'arriving_this_week', label: 'Arriving', icon: Ship, color: 'text-[#0B7C6E]' },
  { key: 'overdue_calls', label: 'Overdue', icon: PhoneOff, color: 'text-red-500' },
  { key: 'open_quotes', label: 'Open Quotes', icon: FileText, color: 'text-blue-500' },
  { key: 'new_leads', label: 'New Leads', icon: UserPlus, color: 'text-violet-500' },
];

const complianceStatItems = [
  { key: 'arriving_this_week', label: 'Arriving', icon: Ship, color: 'text-[#0B7C6E]' },
  { key: 'certificates_expiring', label: 'Certs Expiring', icon: AlertTriangle, color: 'text-amber-500' },
  { key: 'overdue_calls', label: 'Overdue', icon: PhoneOff, color: 'text-red-500' },
  { key: 'open_quotes', label: 'Open Quotes', icon: FileText, color: 'text-blue-500' },
  { key: 'new_leads', label: 'New Leads', icon: UserPlus, color: 'text-violet-500' },
];

const certStatusOptions = [
  { value: 'All', label: 'All Certificates', icon: ShieldCheck, color: 'text-emerald-500' },
  { value: 'expired', label: 'Expired', icon: ShieldX, color: 'text-red-600', countKey: 'cert_expired' },
  { value: 'critical', label: 'Critical (<20 days)', icon: ShieldAlert, color: 'text-red-500', countKey: 'cert_critical' },
  { value: 'warning', label: 'Warning (<60 days)', icon: AlertTriangle, color: 'text-amber-500', countKey: 'cert_warning' },
];

// Port terminal/berth data (matches backend PORT_TERMINALS)
const PORT_TERMINALS = {
  "Mumbai": {"Indira Dock": ["B-01", "B-02", "B-03"], "Jawahar Dweep": ["JD-1", "JD-2"], "Pir Pau": ["PP-1", "PP-2"]},
  "Kandla": {"Kandla Cargo Terminal": ["K-01", "K-02", "K-03"], "Deendayal Terminal": ["D-01", "D-02"]},
  "Kochi": {"Ernakulam Wharf": ["EW-1", "EW-2"], "Mattancherry Wharf": ["MW-1"], "ICTT Vallarpadam": ["V-01", "V-02", "V-03"]},
  "Tuticorin": {"VOC Port Main": ["T-01", "T-02", "T-03"], "Coal Jetty": ["CJ-1"]},
  "Chennai": {"Chennai Container Terminal": ["CCT-1", "CCT-2", "CCT-3"], "Bharathi Dock": ["BD-1", "BD-2"]},
  "Vizag": {"Inner Harbour": ["IH-1", "IH-2", "IH-3"], "Outer Harbour": ["OH-1", "OH-2"]},
  "Mundra": {"Adani Terminal 1": ["AT1-01", "AT1-02", "AT1-03"], "Adani Terminal 2": ["AT2-01", "AT2-02"]},
  "Vizhinjam": {"Vizhinjam International Terminal": ["VIT-1", "VIT-2"]},
  "Rotterdam": {"Europoort": ["E-01", "E-02", "E-03"], "Maasvlakte": ["MV-1", "MV-2", "MV-3"], "Botlek": ["BT-1", "BT-2"]},
  "Amsterdam": {"Westpoort": ["WP-1", "WP-2"], "Amerikahaven": ["AH-1", "AH-2"]},
  "Antwerp": {"Deurganck Dock": ["DD-1", "DD-2", "DD-3"], "Kallo Lock": ["KL-1", "KL-2"]},
  "Houston": {"Barbours Cut": ["BC-1", "BC-2", "BC-3"], "Bayport": ["BP-1", "BP-2"]},
  "Texas City": {"Texas City Terminal": ["TC-1", "TC-2"]},
  "Corpus Christi": {"La Quinta Terminal": ["LQ-1", "LQ-2"], "Inner Harbor": ["IH-1"]},
  "Port Freeport": {"Velasco Terminal": ["VT-1", "VT-2"]},
  "Jebel Ali": {"Terminal 1": ["JA-T1-1", "JA-T1-2", "JA-T1-3"], "Terminal 2": ["JA-T2-1", "JA-T2-2"], "Terminal 3": ["JA-T3-1", "JA-T3-2"]},
  "Singapore": {"Tuas Terminal": ["TT-1", "TT-2", "TT-3"], "Pasir Panjang": ["PP-1", "PP-2", "PP-3"], "Keppel Terminal": ["KT-1", "KT-2"]},
};

export const PortSidebar = ({
  portsByRegion,
  selectedPorts,
  onPortChange,
  stats,
  managers = [],
  owners = [],
  classSocieties = [],
  shipTypes = [],
  selectedManager = 'All',
  selectedOwner = 'All',
  selectedClassSociety = 'All',
  selectedShipType = 'All',
  onManagerChange,
  onOwnerChange,
  onClassSocietyChange,
  onShipTypeChange,
  portCounts = {},
  includeAnchorage = false,
  onAnchorageChange,
  selectedTerminal = 'All',
  onTerminalChange,
  selectedBerth = 'All',
  onBerthChange,
  selectedCertStatus = 'All',
  onCertStatusChange,
}) => {
  const { userRole } = useDashboard();
  const isCompliance = hasMinTier(userRole, 'compliance');
  const [openRegions, setOpenRegions] = useState({ India: true });

  const togglePort = (port) => {
    if (selectedPorts.includes(port)) {
      onPortChange(selectedPorts.filter(p => p !== port));
    } else {
      onPortChange([...selectedPorts, port]);
    }
  };

  const toggleRegion = (region) => {
    setOpenRegions(prev => ({ ...prev, [region]: !prev[region] }));
  };

  // Get available terminals for selected ports
  const availableTerminals = [];
  selectedPorts.forEach(port => {
    const terminals = PORT_TERMINALS[port];
    if (terminals) {
      Object.keys(terminals).forEach(t => {
        if (!availableTerminals.includes(t)) availableTerminals.push(t);
      });
    }
  });

  // Get available berths for selected terminal
  const availableBerths = [];
  if (selectedTerminal !== 'All') {
    selectedPorts.forEach(port => {
      const terminals = PORT_TERMINALS[port];
      if (terminals && terminals[selectedTerminal]) {
        terminals[selectedTerminal].forEach(b => {
          if (!availableBerths.includes(b)) availableBerths.push(b);
        });
      }
    });
  }

  return (
    <div className="sticky top-20 space-y-5" data-testid="port-sidebar">
      {/* Port Filter - Grouped by Region */}
      <div>
        <h2 className="font-heading font-semibold text-xs mb-3 text-muted-foreground tracking-widest uppercase">
          Ports
        </h2>
        <div className="space-y-1">
          {Object.entries(portsByRegion).map(([region, ports]) => (
            <Collapsible key={region} open={openRegions[region]} onOpenChange={() => toggleRegion(region)}>
              <CollapsibleTrigger className="flex items-center gap-1.5 w-full px-2 py-1.5 text-xs font-semibold text-muted-foreground hover:text-foreground transition-colors uppercase tracking-wider">
                {openRegions[region] ? <ChevronDown className="w-3 h-3" /> : <ChevronRight className="w-3 h-3" />}
                {region}
                <span className="text-[10px] font-normal ml-auto">
                  {ports.reduce((sum, p) => sum + (portCounts[p] ?? 0), 0)}
                </span>
              </CollapsibleTrigger>
              <CollapsibleContent>
                <div className="ml-2 space-y-0.5">
                  {ports.map(port => (
                    <label
                      key={port}
                      className="flex items-center gap-2.5 cursor-pointer hover:bg-accent rounded-md px-2 py-1.5 transition-colors"
                      data-testid={`port-filter-${port.toLowerCase().replace(/\s/g, '-')}`}
                    >
                      <Checkbox
                        checked={selectedPorts.includes(port)}
                        onCheckedChange={() => togglePort(port)}
                      />
                      <span className="text-sm">
                        {port}{' '}
                        <span className="text-muted-foreground text-xs">({portCounts[port] ?? 0})</span>
                      </span>
                    </label>
                  ))}
                </div>
              </CollapsibleContent>
            </Collapsible>
          ))}
        </div>
        {selectedPorts.length > 0 && (
          <button
            className="text-xs text-primary hover:underline mt-2 ml-2"
            onClick={() => onPortChange([])}
            data-testid="clear-port-filter"
          >
            Clear all
          </button>
        )}
      </div>

      {/* Terminal / Berth hierarchy */}
      {selectedPorts.length > 0 && availableTerminals.length > 0 && (
        <>
          <Separator />
          <div>
            <h2 className="font-heading font-semibold text-xs mb-2 text-muted-foreground tracking-widest uppercase">
              Terminal
            </h2>
            <Select value={selectedTerminal} onValueChange={(v) => { onTerminalChange(v); onBerthChange('All'); }}>
              <SelectTrigger className="w-full h-9 text-xs" data-testid="filter-terminal-trigger">
                <SelectValue placeholder="All Terminals" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="All">All Terminals</SelectItem>
                {availableTerminals.map(t => (
                  <SelectItem key={t} value={t}>{t}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {selectedTerminal !== 'All' && availableBerths.length > 0 && (
            <div>
              <h2 className="font-heading font-semibold text-xs mb-2 text-muted-foreground tracking-widest uppercase">
                Berth
              </h2>
              <Select value={selectedBerth} onValueChange={onBerthChange}>
                <SelectTrigger className="w-full h-9 text-xs" data-testid="filter-berth-trigger">
                  <SelectValue placeholder="All Berths" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="All">All Berths</SelectItem>
                  {availableBerths.map(b => (
                    <SelectItem key={b} value={b}>{b}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          {/* Anchorage toggle */}
          <div className="flex items-center justify-between px-2">
            <span className="text-xs text-muted-foreground">Include Anchorage</span>
            <Switch
              checked={includeAnchorage}
              onCheckedChange={onAnchorageChange}
              data-testid="anchorage-toggle"
            />
          </div>
        </>
      )}

      <Separator />

      {/* Certificate Status Filter — Tier 2+ only */}
      {isCompliance && (
        <>
          <div>
            <h2 className="font-heading font-semibold text-xs mb-2 text-muted-foreground tracking-widest uppercase">
              Cert Status
            </h2>
            <div className="space-y-1">
              {certStatusOptions.map(option => (
                <button
                  key={option.value}
                  onClick={() => onCertStatusChange?.(option.value)}
                  className={`w-full flex items-center justify-between px-2 py-2 rounded-md text-sm transition-colors ${
                    selectedCertStatus === option.value
                      ? 'bg-primary/10 text-primary font-medium'
                      : 'hover:bg-accent text-muted-foreground'
                  }`}
                  data-testid={`cert-filter-${option.value.toLowerCase()}`}
                >
                  <div className="flex items-center gap-2">
                    <option.icon className={`w-3.5 h-3.5 ${option.color}`} />
                    <span>{option.label}</span>
                  </div>
                  {option.countKey && (
                    <span className={`text-xs font-mono font-bold ${option.color}`}>
                      {stats[option.countKey] ?? 0}
                    </span>
                  )}
                </button>
              ))}
            </div>
          </div>
          <Separator />
        </>
      )}

      {/* Manager Filter */}
      <div>
        <h2 className="font-heading font-semibold text-xs mb-2 text-muted-foreground tracking-widest uppercase">
          Manager
        </h2>
        <Select value={selectedManager} onValueChange={onManagerChange}>
          <SelectTrigger className="w-full h-9 text-xs" data-testid="filter-manager-trigger">
            <SelectValue placeholder="All Managers" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="All" data-testid="filter-manager-all">All Managers</SelectItem>
            {managers.map(m => (
              <SelectItem key={m} value={m} data-testid={`filter-manager-${m}`}>
                {m}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Owner Filter */}
      <div>
        <h2 className="font-heading font-semibold text-xs mb-2 text-muted-foreground tracking-widest uppercase">
          Owner
        </h2>
        <Select value={selectedOwner} onValueChange={onOwnerChange}>
          <SelectTrigger className="w-full h-9 text-xs" data-testid="filter-owner-trigger">
            <SelectValue placeholder="All Owners" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="All" data-testid="filter-owner-all">All Owners</SelectItem>
            {owners.map(o => (
              <SelectItem key={o} value={o} data-testid={`filter-owner-${o}`}>
                {o}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Classification Society Filter */}
      <div>
        <h2 className="font-heading font-semibold text-xs mb-2 text-muted-foreground tracking-widest uppercase">
          Class Society
        </h2>
        <Select value={selectedClassSociety} onValueChange={onClassSocietyChange}>
          <SelectTrigger className="w-full h-9 text-xs" data-testid="filter-class-society-trigger">
            <SelectValue placeholder="All Societies" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="All" data-testid="filter-class-all">All Societies</SelectItem>
            {classSocieties.map(cs => (
              <SelectItem key={cs} value={cs} data-testid={`filter-class-${cs}`}>
                {cs}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      {/* Ship Type Filter */}
      <div>
        <h2 className="font-heading font-semibold text-xs mb-2 text-muted-foreground tracking-widest uppercase">
          Ship Type
        </h2>
        <Select value={selectedShipType} onValueChange={onShipTypeChange}>
          <SelectTrigger className="w-full h-9 text-xs" data-testid="filter-ship-type-trigger">
            <SelectValue placeholder="All Types" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="All" data-testid="filter-ship-type-all">All Types</SelectItem>
            {shipTypes.map(st => (
              <SelectItem key={st} value={st} data-testid={`filter-ship-type-${st}`}>
                {st}
              </SelectItem>
            ))}
          </SelectContent>
        </Select>
      </div>

      <Separator />

      {/* Stats */}
      <div>
        <h2 className="font-heading font-semibold text-xs mb-3 text-muted-foreground tracking-widest uppercase">
          Overview
        </h2>
        <div className="space-y-3">
          {(isCompliance ? complianceStatItems : statItems).map(item => (
            <div key={item.key} className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <item.icon className={`w-3.5 h-3.5 ${item.color}`} />
                <span className="text-xs text-muted-foreground">{item.label}</span>
              </div>
              <span className="font-heading font-bold text-lg leading-none">
                {stats[item.key] ?? 0}
              </span>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};
